window.ENEM_RESOLUTION_CHUNKS=window.ENEM_RESOLUTION_CHUNKS||{};window.ENEM_RESOLUTION_CHUNKS["data/resolucoes/linguagens_2022.js"]=[{"title":"Uma infância em uma comunidade de exilados","steps":["A metáfora made, assembled, imported sintetiza os deslocamentos da família.","Em Miami, professores, colegas e trabalhadores cubanos compunham o cotidiano do narrador.","D resume esse cenário de integração, marcado por uma comunidade culturalmente insular, não por assimilação completa."],"alternatives":{"A":"A escola é um dos lugares citados, mas não há avaliação de sua qualidade.","B":"Predominar na comunidade do narrador não equivale a prestígio em todo o país.","C":"As profissões exemplificam o convívio, não oportunidades de capacitação.","D":"O relato mostra como a comunidade cubana organizava a experiência do imigrante nos Estados Unidos.","E":"O foco não é a intensificação dos vínculos entre parentes, mas o ambiente comunitário."},"takeaway":"Leia exemplos como apoio à ideia central: a enumeração de profissões descreve o entorno social.","key":"linguagens:L502","area":"linguagens","year":2022,"number":1,"answer":"D","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[2,3],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"As expectativas amorosas mudam menos do que parecem","steps":["O início descreve critérios de escolha de parceiros no tempo de Jane Austen.","A pergunta how much has — or hasn’t — changed introduz a comparação com aplicativos atuais.","C expressa a permanência de expectativas econômicas e estéticas entre épocas distintas."],"alternatives":{"A":"Papéis de gênero aparecem no começo, mas o propósito engloba a comparação histórica.","B":"Educação e habilidades são exemplos antigos, não a tese sobre educação formal atual.","C":"O passado e os perfis digitais são comparados por suas exigências sociais e econômicas.","D":"Aplicativos são o contraponto contemporâneo, não o único objeto da discussão.","E":"O texto critica exigências estéticas e classistas, em vez de valorizá-las."},"takeaway":"Perguntas de transição e conectores ajudam a identificar a relação entre os dois blocos de um texto.","key":"linguagens:L503","area":"linguagens","year":2022,"number":2,"answer":"C","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[2,4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A biblioteca transforma o castelo ameaçador em oportunidade","steps":["O marido descreve barreiras, criaturas e a própria transformação em fera.","A mulher responde com entusiasmo pelos livros e planeja ficar lendo.","B explica a quebra de expectativa: o gosto pela leitura supera a intimidação, sem indicar preferência específica por terror."],"alternatives":{"A":"Ela diz não acreditar na própria sorte em tom positivo, não de revolta.","B":"Suas falas sobre a biblioteca e permanecer lendo evidenciam prazer na leitura.","C":"A personagem não reage às ameaças com medo do casamento.","D":"O conteúdo dos livros não é informado: não se pode restringi-lo ao terror.","E":"Ela acolhe a biblioteca como vantagem, em vez de rejeitar a residência."},"takeaway":"Em tirinhas, compare a expectativa criada por uma fala com a reação efetiva da outra personagem.","key":"linguagens:L504","area":"linguagens","year":2022,"number":3,"answer":"B","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[2,4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Downsides anuncia efeitos negativos da comparação social","steps":["O primeiro bloco apresenta funções da plataforma.","Downsides marca a passagem para insegurança, ansiedade e depressão associadas à comparação com vidas idealizadas.","D corresponde ao efeito negativo destacado, sem transformar o texto em diagnóstico de todo usuário."],"alternatives":{"A":"Recursos de fotografia são funcionalidades, não a desvantagem introduzida.","B":"O texto diz que aspectos negativos da vida raramente são mostrados.","C":"Busca por aceitação existe, mas o trecho enfatiza o sofrimento ligado a ela.","D":"Ansiedade entre adolescentes aparece expressamente entre as consequências discutidas.","E":"Aproximar pessoas não traduz a orientação negativa de downsides."},"takeaway":"Inferir uma palavra pelo contexto exige observar o campo semântico das frases que vêm depois.","key":"linguagens:L505","area":"linguagens","year":2022,"number":4,"answer":"D","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[3,4],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Mensagens escritas não preenchem a ausência da voz","steps":["A repetição de text enfatiza a comunicação por mensagens.","Expressões como broken chord, blurred e will ever be heard sugerem perda de presença e de som.","E sintetiza insatisfação com esse modo de comunicação, não acusação explícita contra o interlocutor."],"alternatives":{"A":"O campo de imagens de ferida e ruptura impede uma leitura de pleno contentamento.","B":"O cuidado com o aparelho aparece, mas não resume a angústia do poema.","C":"Não se trata de uma preocupação técnica com a qualidade da escrita.","D":"Não há denúncia clara de uma conduta ofensiva da outra pessoa.","E":"A voz poética sente limites e insuficiência na troca mediada por mensagens."},"takeaway":"O sentimento central de um poema costuma resultar de várias imagens, e não de um verbo isolado.","key":"linguagens:L506","area":"linguagens","year":2022,"number":5,"answer":"E","subject":"Inglês","topic":"Interpretação de textos em língua inglesa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[3,5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Metáforas cotidianas aproximam autora e leitor","steps":["O artigo critica a pressa afetiva em linguagem próxima da conversa.","A vida engatar a primeira transporta uma imagem cotidiana de dirigir para o ritmo de viver.","E identifica essa construção coloquial; metáfora não é sempre informal, mas aqui o modo de formulá-la produz esse efeito."],"alternatives":{"A":"A construção impessoal não determina, sozinha, o grau de formalidade.","B":"Pressa pertence ao tema da urgência, não prova o registro distenso.","C":"Repetição sintática pode existir em registros formais e informais.","D":"A hipérbole amplia uma imagem, mas não é a marca selecionada de aproximação coloquial.","E":"A expressão automobilística cotidiana torna a crítica concreta e conversacional."},"takeaway":"Diferencie o recurso existente no texto daquele que responde ao efeito específico pedido no comando.","key":"linguagens:L224","area":"linguagens","year":2022,"number":6,"answer":"E","subject":"Variação linguística","topic":"Oralidade, registros e adequação comunicativa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[5],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Um cão comunitário complica a ideia de que todo cão precisa de dono","steps":["O cartaz convoca o público a levar um animal para casa.","A narrativa mostra um cão que construiu vínculos na cidade sem ser preso a um domicílio.","A indica problematização: o segundo texto amplia a reflexão sobre cuidado, rua e comunidade, sem promover abandono."],"alternatives":{"A":"A história do cão comunitário relativiza a adoção doméstica como única experiência de proteção e vínculo.","B":"Não se narra uma relação entre um animal adotado e seu proprietário.","C":"O segundo texto não reafirma diretamente o chamado para levar o cão para casa.","D":"O relato não compara o temperamento de cães e gatos.","E":"Não há uma convocação publicitária à campanha no segundo texto."},"takeaway":"Comparar textos inclui reconhecer tensão e ampliação de perspectiva, não só coincidência de tema.","key":"linguagens:L147","area":"linguagens","year":2022,"number":7,"answer":"A","subject":"Interpretação de texto e gêneros textuais","topic":"Intertextualidade e relações entre textos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Trocar aparência por realizações tem alcance formativo","steps":["A nova versão do jogo destaca mulheres de diferentes profissões e origens.","As perguntas passam de traços físicos para descobertas, prêmios e ações.","A identifica uma contribuição para a formação cidadã: reconhecer trajetórias e participação de mulheres."],"alternatives":{"A":"Conhecer realizações e diversidade de mulheres amplia referências sociais dos jogadores.","B":"A mudança não se reduz a discutir padrões de beleza e elegância.","C":"A arrecadação é narrada, mas não se pretende intensificar disputa entre compradores.","D":"O financiamento explica a produção; não é a finalidade principal da adaptação.","E":"O caráter lúdico é meio para conhecer trajetórias, não conteúdo exclusivo da atualidade."},"takeaway":"Distingua a informação acessória sobre financiar um projeto do valor social atribuído ao projeto.","key":"linguagens:L095","area":"linguagens","year":2022,"number":8,"answer":"A","subject":"Interpretação de texto e gêneros textuais","topic":"Argumentação e pontos de vista","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O arrependimento é um peso que o condutor carrega","steps":["A campanha associa causar um acidente a carregar algo pelo resto da vida.","A palavra arrependimento e a representação visual tornam concreta uma consequência moral duradoura.","A reconhece o apelo à culpa de quem provoca o acidente, articulado ao imperativo de não beber ao dirigir."],"alternatives":{"A":"O foco está na consciência e no arrependimento do responsável pelo acidente.","B":"A mensagem não se centra no acompanhamento psicológico de quem sofreu a colisão.","C":"Não se apresentam medidas de monitoramento pelas autoridades.","D":"A estratégia não anuncia pena jurídica ou fiscalização da alcoolemia.","E":"A perda de familiares pode causar dor, mas o apelo específico é a culpa do causador."},"takeaway":"Publicidade pode persuadir por identificação com uma consequência emocional, sem apresentar números ou punições.","key":"linguagens:L148","area":"linguagens","year":2022,"number":9,"answer":"A","subject":"Interpretação de texto e gêneros textuais","topic":"Intertextualidade e relações entre textos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":true,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[6],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Reproduzir com facilidade também ameaça a proteção autoral","steps":["As tecnologias ampliam criação, circulação e compartilhamento.","O texto contrapõe essa abertura aos problemas de autoria e intervenção sem autorização.","C sintetiza o risco para a proteção da produção estética; o problema não é a simples existência da distribuição digital."],"alternatives":{"A":"O texto não prevê fracasso comercial necessário dos artistas.","B":"Suportes são meios de criação; sua valorização não é o direito ameaçado.","C":"Reprodução e intervenção não autorizadas podem comprometer a proteção da obra e da autoria.","D":"A distribuição se amplia; o risco salientado diz respeito aos direitos sobre o que circula.","E":"Compartilhar é facilitado, não apresentado como capacidade ameaçada."},"takeaway":"Quando o texto apresenta vantagens e uma ressalva, localize exatamente o objeto da ressalva.","key":"linguagens:L730","area":"linguagens","year":2022,"number":10,"answer":"C","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Toda tecnologia nova também exige aprendizagem","steps":["O texto começa reproduzindo a pretensão de que a novidade dispensaria aprender.","A expressão na realidade inverte essa expectativa.","A conclusão afirma uma longa iniciação em nova linguagem, dificultada pelos hábitos anteriores: alternativa A."],"alternatives":{"A":"O impacto enfatizado é aprender códigos e práticas diferentes dos já incorporados.","B":"Valorizar a ferramenta não equivale à dificuldade cognitiva discutida.","C":"Mudanças recorrentes são contexto, não o obstáculo descrito pelo autor.","D":"O conhecimento anterior persiste e interfere; não desaparece imediatamente.","E":"A rapidez é justamente a expectativa contestada pelo texto."},"takeaway":"Não atribua ao autor a tese que ele apresenta primeiro apenas para refutá-la depois.","key":"linguagens:L784","area":"linguagens","year":2022,"number":11,"answer":"A","subject":"Tecnologias da Informação e Comunicação","topic":"Tecnologias, comunicação e transformações sociais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Adequação não é corrigir toda conversa pela norma-padrão","steps":["Os personagens estão em uma troca informal.","Correções incessantes de pronomes interrompem a interação e geram conflito.","B aponta inadequação ao contexto, não inutilidade da norma-padrão em todos os usos."],"alternatives":{"A":"Não há evidência de diferença geracional como causa do conflito.","B":"A situação informal não exige a vigilância gramatical imposta pelo interlocutor.","C":"A grosseria é um efeito da interação; o critério linguístico central é a situação comunicativa.","D":"O texto não informa a escolaridade dos participantes para sustentar essa explicação.","E":"Não há dados suficientes para atribuir o conflito a classes sociais diferentes."},"takeaway":"Conhecer a norma-padrão inclui saber quando uma situação pede registro formal e quando admite outros usos.","key":"linguagens:L191","area":"linguagens","year":2022,"number":12,"answer":"B","subject":"Variação linguística","topic":"Variedades linguísticas, identidade e preconceito","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[7],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A desigualdade social reaparece no acesso digital","steps":["Os autores relacionam acesso e práticas digitais a escolaridade, renda e outros marcadores.","Os grupos já desfavorecidos aparecem com menor acesso à rede.","B questiona a ideia de democratização automática da informação; o texto destaca reprodução de exclusões."],"alternatives":{"A":"Não se formula o crescimento econômico como solução única do problema.","B":"Os dados contrariam a ideia de que o ambiente digital já oferece oportunidades equivalentes a todos.","C":"O uso comercial não é apresentado como a causa exclusiva da exclusão.","D":"Os autores afirmam o vínculo com escolaridade, em vez de refutá-lo.","E":"Políticas inclusivas podem ser pertinentes, mas o trecho não estabelece essa condição como sua conclusão."},"takeaway":"Uma inferência social plausível não substitui a tese efetivamente defendida pelos dados apresentados.","key":"linguagens:L731","area":"linguagens","year":2022,"number":13,"answer":"B","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O léxico registra experiências e preconceitos sociais","steps":["O primeiro texto afirma que a língua classifica a realidade e condensa experiências.","O segundo mostra expressões associadas à cor negra em avaliações negativas.","D explicita, na argumentação dos textos, a incorporação histórica de preconceitos em escolhas lexicais."],"alternatives":{"A":"A disponibilidade de palavras é uma descrição geral, sem explicar a discriminação discutida.","B":"Os exemplos não são apresentados como invenções para nomear realidades recém-surgidas.","C":"A mera presença no acervo do idioma não explica sua carga social discriminatória.","D":"O vínculo entre experiência social e léxico é concretizado pela reprodução de preconceitos.","E":"As expressões não constituem descrição neutra e objetiva da realidade."},"takeaway":"O item pede a relação defendida entre os textos, não uma análise etimológica isolada de cada expressão.","key":"linguagens:L096","area":"linguagens","year":2022,"number":14,"answer":"D","subject":"Interpretação de texto e gêneros textuais","topic":"Argumentação e pontos de vista","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Um post adapta a linguagem publicitária para divulgar um projeto","steps":["A peça usa chamada breve, composição visual e pergunta ao leitor.","O conteúdo informa uma proposta de divulgar o custo da publicidade oficial.","B identifica a finalidade de tornar conhecido um projeto sobre transparência, não a garantia de que ele já esteja em vigor."],"alternatives":{"A":"A mensagem tem como foco divulgar uma proposta específica, não um manual de publicidade adequada.","B":"O post comunica ao público a proposta de transparência dos gastos em anúncios.","C":"O convite à opinião não transfere ao cidadão a responsabilidade integral de controle.","D":"O público não recebe a gestão nem a redação dos projetos de lei.","E":"Dar publicidade à proposta não assegura por si a fiscalização efetiva dos gastos."},"takeaway":"Diferencie divulgar uma medida proposta de garantir que seus resultados já estejam acontecendo.","key":"linguagens:L052","area":"linguagens","year":2022,"number":15,"answer":"B","subject":"Interpretação de texto e gêneros textuais","topic":"Gêneros textuais e finalidades comunicativas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[8],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A resenha apresenta e avalia o filme","steps":["O primeiro bloco recupera a trajetória de Elena e a produção de Petra.","O fechamento formula juízos sobre memória, legado e delicadeza.","E identifica a resenha crítica: a narrativa biográfica serve à avaliação do filme, não se confunde com ele."],"alternatives":{"A":"Narrar por imagens e poesia é uma característica atribuída ao filme, não ao texto jornalístico.","B":"Memórias e separação são conteúdos da obra analisada, não a função social do gênero.","C":"O texto não apenas resume cenas: interpreta e aprecia a obra.","D":"O articulista não é apresentado como autor autobiográfico do filme.","E":"A apresentação do filme se combina a interpretações e juízos que orientam o leitor."},"takeaway":"Quando a questão pergunta o gênero, observe o que o texto faz com seu assunto: informar, avaliar, instruir ou convocar.","key":"linguagens:L053","area":"linguagens","year":2022,"number":16,"answer":"E","subject":"Interpretação de texto e gêneros textuais","topic":"Gêneros textuais e finalidades comunicativas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O verbete ganha corpo e alma pela metáfora","steps":["O começo imita a classificação de um dicionário.","Logo, palavras recebem alma e ações: nuvem chove, triste chora, fogo queima.","B identifica o trabalho figurativo que converte a definição em elaboração poética, e não só um texto sobre poesia."],"alternatives":{"A":"Falar do fazer poético não torna automaticamente qualquer texto um poema.","B":"Atribuir corpo e alma às palavras cria um sentido figurado, além da definição técnica.","C":"A enumeração gramatical inicial é justamente o ponto que o texto ultrapassa.","D":"A comparação isolada não é o recurso central indicado para a poeticidade.","E":"Informar a classificação gramatical caracteriza o verbete técnico, não explica sua transformação."},"takeaway":"Tema e modo de dizer são diferentes: um texto poético trabalha expressivamente a linguagem.","key":"linguagens:L316","area":"linguagens","year":2022,"number":17,"answer":"B","subject":"Gramática a serviço do sentido","topic":"Sintaxe, pontuação e relações de sentido","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Fragmentos justapostos encenam uma percepção irritada","steps":["Há sequências nominais como Mosaico estúpido e Buraco, cratera, pedra solta.","Elas se alternam com frases verbais, ordens, perguntas e comentários do narrador.","A identifica a justaposição desses segmentos, produzindo um ritmo descontínuo ligado à experiência do idoso."],"alternatives":{"A":"A alternância de fragmentos nominais e sequências verbais organiza o relato.","B":"Referências ao passado existem, mas não constituem o principal princípio estrutural.","C":"Adjetivos avaliam o cenário, porém não explicam a composição fragmentária do conjunto.","D":"Os substantivos não são todos sinônimos: apontam diferentes obstáculos e objetos.","E":"Predomina a aproximação direta de segmentos, não uma rede explícita de conectivos lógicos."},"takeaway":"Para reconhecer estrutura, observe como os segmentos se encadeiam, não apenas quais palavras aparecem.","key":"linguagens:L338","area":"linguagens","year":2022,"number":18,"answer":"A","subject":"Gramática a serviço do sentido","topic":"Classes de palavras, referenciação e efeitos de sentido","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[9],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A violência esportiva é situada no quadro social mais amplo","steps":["O episódio no estádio abre a discussão, mas não é tratado como caso isolado.","O texto critica uma resposta apenas repressiva e relaciona o futebol ao panorama nacional.","C identifica a violência como reflexo da precariedade da organização social do país."],"alternatives":{"A":"Embora comece no Rio, o texto apresenta números nacionais e amplia o diagnóstico.","B":"Responsabilizar apenas torcidas repete a limitação que o próprio texto critica.","C":"A conclusão associa a violência futebolística à desordem pública, social, econômica e política.","D":"Não se explica o problema simplesmente pela dimensão física dos estádios.","E":"Não há atribuição causal à insatisfação dos clubes com o calendário ou a organização."},"takeaway":"O alcance da conclusão pode ser maior que o do exemplo usado para abrir uma argumentação.","key":"linguagens:L700","area":"linguagens","year":2022,"number":19,"answer":"C","subject":"Educação Física","topic":"Cultura corporal, jogos e lazer","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Saúde ampliada exige considerar condições sociais de acesso","steps":["Os dados mostram forte associação entre prática corporal, escolaridade e renda.","A falta de tempo e de interesse aparece mais que a falta de instalações.","C propõe facilitar a prática articulando educação e distribuição de renda, em vez de responsabilizar apenas a vontade individual."],"alternatives":{"A":"Melhorar aptidão pode ser resultado, mas a proposta ignora os condicionantes sociais evidenciados.","B":"Combater sedentarismo repete o objetivo geral sem incorporar a análise ampliada dos dados.","C":"Educação e condições econômicas interferem nas oportunidades de adotar exercícios regularmente.","D":"O texto informa que falta de instalações foi pouco citada, enfraquecendo a solução centrada só nelas.","E":"Incentivo fiscal específico não decorre dos resultados apresentados pela pesquisa."},"takeaway":"Em saúde coletiva, diferencie prescrever uma conduta de criar condições sociais para que ela seja possível.","key":"linguagens:L676","area":"linguagens","year":2022,"number":20,"answer":"C","subject":"Educação Física","topic":"Corpo, saúde e qualidade de vida","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[10],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O discurso abolicionista confronta a moral de quem sustenta a escravidão","steps":["A personagem invoca a liberdade e valores religiosos e cívicos.","Esses valores entram em contradição com a defesa do trabalho forçado.","B identifica a exposição da hipocrisia conservadora; os argumentos econômicos se somam à condenação moral."],"alternatives":{"A":"A referência cristã fundamenta a crítica à escravidão, não descreve imposição religiosa aos escravizados.","B":"A defesa da escravidão é confrontada com a moral religiosa e cívica que a deveria condenar.","C":"A fala repudia a violência escravista; não a recomenda como meio de progresso.","D":"O problema apontado é o sistema de trabalho forçado, não uma suposta incapacidade racial.","E":"Predominam denúncia e indignação explícitas, não uma ironia sobre o comportamento de fazendeiros."},"takeaway":"No abolicionismo, referências morais e econômicas podem convergir sem atribuir inferioridade às pessoas escravizadas.","key":"linguagens:L472","area":"linguagens","year":2022,"number":21,"answer":"B","subject":"Literatura","topic":"Romantismo","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Dois projetos tornam o conhecimento mais acessível","steps":["O Mural Eletrônico oferece informação por diferentes interfaces.","O Surdonews traduz notícias para Libras e busca preservar sua complexidade.","E identifica o objetivo compartilhado de disseminar conhecimento, sem supor igualdade social já garantida pelos projetos."],"alternatives":{"A":"Promover acesso é uma contribuição, mas não garante igualdade em todas as dimensões.","B":"Somente o segundo projeto é atribuído a uma pesquisadora surda.","C":"A origem no mestrado é informada para o segundo projeto, não para ambos.","D":"A página em rede social não está restrita ao espaço físico de uma escola.","E":"Ambos procuram remover barreiras à circulação de informação e conhecimento."},"takeaway":"Uma semelhança entre textos precisa ser verdadeira para os dois, sem universalizar um detalhe de apenas um.","key":"linguagens:L149","area":"linguagens","year":2022,"number":22,"answer":"E","subject":"Interpretação de texto e gêneros textuais","topic":"Intertextualidade e relações entre textos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O olhar associa a personagem a sofrimentos de outras gerações","steps":["A descrição dos olhos desencadeia associações sobre homens aventureiros e mulheres sofredoras.","O narrador se afasta do traço físico e percorre memória, origem e expectativas frustradas.","E reconhece esse movimento de consciência marcado por antigos sofrimentos; não basta reduzir a passagem à ascendência."],"alternatives":{"A":"A origem cruzada aparece, mas não abrange o movimento associativo e a memória de sofrimento.","B":"Não há uma sequência de conquistas familiares desenvolvendo o enredo.","C":"As mulheres acompanham os homens, mas não se narra diretamente um conflito conjugal específico.","D":"O trecho enfatiza a precariedade do lar desejado, não o desejo atual de imitar os antepassados.","E":"O detalhe dos olhos abre um fluxo de associações sobre experiências e dores antigas."},"takeaway":"Em prosa introspectiva, uma descrição física pode ser ponto de partida para memória e associação subjetiva.","key":"linguagens:L433","area":"linguagens","year":2022,"number":23,"answer":"E","subject":"Literatura","topic":"Modernismo: romance de 1930 e prosa da segunda geração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[11],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O pedido de pão mostra que falar bem depende da situação","steps":["O autor constrói um pedido excessivamente jurídico em uma padaria.","Depois o contrapõe a uma formulação cotidiana, simples e clara.","E explica o humor e a crítica: adequar a linguagem ao interlocutor, ao objetivo e ao contexto."],"alternatives":{"A":"Conhecimento jurídico não é necessário para comprar pão com clareza.","B":"Parecer inteligente é o valor social que o artigo questiona.","C":"O autor rejeita a equivalência automática entre rebuscamento e inteligência.","D":"Documentos jurídicos aparecem como contraponto, mas não explicam o exemplo da padaria.","E":"A linguagem técnica pode servir a certos contextos e ser inadequada em uma compra cotidiana."},"takeaway":"Adequação não é proibir palavras difíceis: é escolher recursos que funcionem na situação real.","key":"linguagens:L225","area":"linguagens","year":2022,"number":24,"answer":"E","subject":"Variação linguística","topic":"Oralidade, registros e adequação comunicativa","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A medalha questiona a divisão de esportes por gênero","steps":["A jornalista relaciona o skate à liberdade de não se encaixar em padrões.","Compara expectativas de delicadeza impostas às meninas à tolerância ao risco para os meninos.","C identifica a desconstrução do skate como território exclusivamente masculino."],"alternatives":{"A":"A experiência da jornalista exemplifica sua posição, mas não é o problema social central.","B":"A participação feminina é contexto; a fala discute os estereótipos que a limitam.","C":"O questionamento busca romper a associação entre modalidade esportiva e um gênero obrigatório.","D":"Ser a mais jovem é dado da conquista, não a relação de gênero analisada.","E":"A medalha inicia o assunto, mas a tese diz respeito a padrões sociais mais amplos."},"takeaway":"Reconheça quando uma conquista individual é usada para discutir barreiras coletivas de participação.","key":"linguagens:L701","area":"linguagens","year":2022,"number":25,"answer":"C","subject":"Educação Física","topic":"Cultura corporal, jogos e lazer","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[12],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A cidade não mora em mim exprime uma experiência subjetiva","steps":["O comando já reconhece a predominância da função poética.","Pede localizar a função emotiva: a manifestação da interioridade do eu lírico.","C combina a primeira pessoa em mim com o sentimento de afastamento da cidade."],"alternatives":{"A":"O deslocamento coloquial, isoladamente, não explicita a experiência íntima do eu.","B":"A referência ao espaço da feira descreve um ambiente externo.","C":"A metáfora em primeira pessoa exprime a relação afetiva e subjetiva com a cidade.","D":"O verso caracteriza uma paisagem e sua transformação, sem a mesma marca subjetiva.","E":"O vocativo chama interlocutores e se aproxima da função conativa."},"takeaway":"Funções coexistem: procure a marca que responde ao recorte do comando, mesmo em um texto predominantemente poético.","key":"linguagens:L289","area":"linguagens","year":2022,"number":26,"answer":"C","subject":"Funções e figuras de linguagem","topic":"Funções da linguagem","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Riscar o estereótipo muda o sentido do slogan","steps":["As frases evocam clichês sobre mulheres ao volante e homens que choram.","Os trechos riscados e a imagem de um homem chorando desautorizam essas fórmulas.","B identifica a revisão dos estereótipos, não sua confirmação literal."],"alternatives":{"A":"A peça não pretende fixar diferenças naturais entre os gêneros.","B":"Texto, rasuras e fotografias convidam a reconsiderar representações rígidas de gênero.","C":"O combate ao sexismo é compatível, mas não se prescreve uma medida preventiva concreta.","D":"Ler as frases sem as rasuras produz o contrário do efeito pretendido.","E":"Não há simples repetição neutra de opiniões: as intervenções contestam os clichês."},"takeaway":"Rasura, tipografia e imagem também argumentam: o verbal não deve ser lido como se estivesse sem edição.","key":"linguagens:L339","area":"linguagens","year":2022,"number":27,"answer":"B","subject":"Gramática a serviço do sentido","topic":"Classes de palavras, referenciação e efeitos de sentido","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Recuperar a língua é resistir e conservar memória","steps":["A perda linguística aparece ligada a perseguição e dispersão do povo pataxó.","O reaprendizado reconecta gerações a uma forma de se reconhecer e narrar a própria história.","B reúne resistência étnica e preservação de memória cultural."],"alternatives":{"A":"Denunciar a violência é parte do processo, mas não esgota o caráter identitário da recuperação.","B":"Retomar a língua enfrenta o apagamento e mantém formas culturais de pertencer ao povo.","C":"A universidade participa da trajetória, mas a identidade não se reduz ao meio acadêmico.","D":"O retorno ao território importa, porém o comando pede o papel identitário da língua.","E":"Aumentar uma contagem de línguas não exprime o sentido histórico e cultural do movimento."},"takeaway":"Língua é prática social e memória coletiva; sua recuperação não é apenas aprendizagem de vocabulário.","key":"linguagens:L267","area":"linguagens","year":2022,"number":28,"answer":"B","subject":"Variação linguística","topic":"História da língua e diversidade cultural","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[13],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A simplicidade aparente contrasta com a sagacidade da vidente","steps":["Roupas e objetos sugerem uma figura simples.","Os olhos são descritos como penetrantes e capazes de revolver o coração das visitantes.","D identifica a mistura de singeleza e astúcia, acentuada pela pergunta sobre os filhos após receber seus retratos."],"alternatives":{"A":"A ironia não está simplesmente em ridicularizar a roupa dos moradores do morro.","B":"Não se desenvolve aqui uma discussão explícita sobre estratégias de renda.","C":"O mistério é associado principalmente à vidente e a seu olhar, não às clientes.","D":"A figura singela é investida de olhar agudo e habilidade para conduzir a situação.","E":"O interesse por mulheres não explica o mecanismo específico do contraste narrativo."},"takeaway":"Na ironia machadiana, observe o descompasso entre aparência, gesto e informação disponível ao personagem.","key":"linguagens:L458","area":"linguagens","year":2022,"number":29,"answer":"D","subject":"Literatura","topic":"Realismo e Naturalismo — Machado de Assis e outros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O narrador explica a emoção como instinto biológico","steps":["A ternura aparente de Margarida é explicitamente negada como sentimento cristão.","O narrador a interpreta como instinto de maternidade e simpatia carnal.","C reconhece a influência cientificista do Naturalismo, sem adotar essa redução como verdade científica atual."],"alternatives":{"A":"A divisão de tarefas aparece, mas não explica a leitura biologizante dos sentimentos.","B":"Não há defesa de igualdade de condições entre pessoas escravizadas e livres.","C":"O vocabulário de instinto e corpo trata o comportamento como fenômeno biológico.","D":"A interpretação religiosa é expressamente afastada pela voz narrativa.","E":"O narrador não explica a ação como afeto altruísta e respeito mútuo."},"takeaway":"Identificar uma visão cientificista de época não significa endossar seus determinismos como ciência contemporânea.","key":"linguagens:L459","area":"linguagens","year":2022,"number":30,"answer":"C","subject":"Literatura","topic":"Realismo e Naturalismo — Machado de Assis e outros","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A imagem dos retirantes expõe uma realidade social dramática","steps":["O narrador aproxima os corpos de esqueletos e fantasmas.","A falta de rumo, a fome e a fraqueza tornam concreta a experiência do deslocamento forçado.","A identifica a representação crua do drama dos retirantes, característica da prosa social associada ao Romance de 30."],"alternatives":{"A":"A descrição dos corpos e da caminhada evidencia materialmente o sofrimento da retirada.","B":"A ausência de destino acentua o drama, mas não é o recurso composicional central.","C":"O trecho enfatiza sinais corporais e condições coletivas, não análise psicológica individual.","D":"A denúncia social existe, mas não se explicita filiação ou ação política do narrador.","E":"O sol é agente hostil da fuga, não objeto principal de contemplação lírica."},"takeaway":"A bagaceira, de 1928, antecipa tendências da prosa regionalista social depois associadas ao Romance de 30.","key":"linguagens:L434","area":"linguagens","year":2022,"number":31,"answer":"A","subject":"Literatura","topic":"Modernismo: romance de 1930 e prosa da segunda geração","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[14],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"As orientações variam conforme a faixa etária","steps":["A peça apresenta um guia para famílias e pediatras.","Suas colunas distinguem até dois anos, de dois a cinco e até dez anos.","A resume a finalidade: propor cuidados específicos para etapas da infância, segundo as orientações históricas reproduzidas no item."],"alternatives":{"A":"A divisão por idade organiza recomendações diferentes sobre exposição e acesso às telas.","B":"O caráter de orientação não autoriza resumir a peça como obediência rígida sem contexto.","C":"Alguns efeitos são mencionados, mas a estrutura é de recomendações por idade.","D":"O texto não propõe rituais como seu eixo organizador.","E":"A formulação é genérica e não capta o critério etário que estrutura o manual."},"takeaway":"A interpretação de um material de saúde histórico não equivale a uma recomendação clínica atual personalizada.","key":"linguagens:L732","area":"linguagens","year":2022,"number":32,"answer":"A","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O inventário resulta da enumeração de objetos e acontecimentos","steps":["O trecho acumula elementos do velório e do enterro.","Objetos, pessoas e ações aparecem em sucessão: caixão, convidados, rezas, transporte.","A identifica a enumeração, responsável pelo efeito de lista que o narrador chama inventário."],"alternatives":{"A":"O acúmulo de itens e acontecimentos compõe uma espécie de relação de tudo que cercou o funeral.","B":"O narrador comenta sua escrita e avalia o capítulo; não basta alegar objetividade.","C":"Um período longo pode ter outras estruturas, sem constituir inventário.","D":"A alternância temporal não é o que produz a forma de listagem.","E":"O vocabulário fúnebre define o assunto, mas uma narrativa de funeral nem sempre é inventário."},"takeaway":"Tema responde ao que se fala; procedimento composicional responde a como os elementos são organizados.","key":"linguagens:L340","area":"linguagens","year":2022,"number":33,"answer":"A","subject":"Gramática a serviço do sentido","topic":"Classes de palavras, referenciação e efeitos de sentido","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[15],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Adaptar o equipamento permite reinventar o espaço de prática","steps":["Praticantes de snowboard queriam continuar a atividade sem neve.","Criaram uma prancha com rodas e pneus para diferentes superfícies.","D identifica a criatividade para adaptar a prática a novos espaços, não a exigência de um único terreno regulamentado."],"alternatives":{"A":"Há circuito competitivo, mas a origem descrita não depende de rivalidade.","B":"A padronização técnica não explica a invenção diante da ausência de neve.","C":"O texto destaca uma adaptação criativa, não a criação de regras previamente fixadas.","D":"Modificar o equipamento abriu possibilidades em grama, terra, asfalto e outros terrenos.","E":"A variedade de pisos contraria a exigência de espaço único e definido."},"takeaway":"Uma modalidade de aventura pode nascer da ressignificação de equipamento e ambiente de outra prática.","key":"linguagens:L659","area":"linguagens","year":2022,"number":34,"answer":"D","subject":"Educação Física","topic":"Esporte, inclusão e práticas corporais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A brevidade da crônica entra em tensão com o desejo de profundidade","steps":["A autora compara o jornal, aberto a muitos, ao livro escolhido pelo leitor.","Pergunta se deve ser leve, divertir e ocupar poucos minutos.","C identifica a brevidade do tratamento como uma expectativa do gênero que provoca sua inquietação."],"alternatives":{"A":"A autora fala diretamente com o leitor e nota até excesso de pessoalidade.","B":"Não se discute a montagem de múltiplas tramas simultâneas.","C":"A preocupação com leitura breve e leve contrasta com a comunicação profunda desejada.","D":"A descrição minuciosa de personagens não é o objeto da reflexão.","E":"O jornal é descrito como acessível a todo mundo, não a um grupo exclusivo."},"takeaway":"Reflexões sobre o gênero podem problematizar suas expectativas, sem negar que o texto pertença a ele.","key":"linguagens:L054","area":"linguagens","year":2022,"number":35,"answer":"C","subject":"Interpretação de texto e gêneros textuais","topic":"Gêneros textuais e finalidades comunicativas","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Informar a gravidade também é conscientizar","steps":["A notícia apresenta uma proposta de vacinação e seu andamento legislativo.","Ao explicar que a doença é grave e atinge humanos e cães, amplia a percepção do problema.","C identifica conscientização sobre saúde pública, sem atribuir à reportagem autoria do projeto ou garantia de sua aprovação."],"alternatives":{"A":"A notícia acompanha uma decisão, mas não realiza auditoria ou fiscalização técnica das ações.","B":"A gratuidade integra a proposta, mas não há uma defesa geral de todos os serviços gratuitos.","C":"Esclarecer gravidade, transmissão e alcance social contribui para conscientizar o público.","D":"A campanha é proposta pelo projeto noticiado, não criada pela própria reportagem.","E":"O texto não denuncia demora nem atribui culpa a gestores específicos."},"takeaway":"Jornalismo informativo pode produzir conscientização sem ser uma campanha institucional ou um parecer médico.","key":"linguagens:L005","area":"linguagens","year":2022,"number":36,"answer":"C","subject":"Interpretação de texto e gêneros textuais","topic":"Recursos expressivos e construção de sentidos","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[16],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A felicidade editada vira exigência permanente","steps":["Influenciadores exibem uma vida sem conflitos nem tristeza.","A repetição desse recorte cria pressão para que o público pareça feliz o tempo todo.","A identifica uma representação superficial e estereotipada de felicidade, mais ampla que um padrão de beleza."],"alternatives":{"A":"A aparência de felicidade constante transforma um recorte editado em padrão irreal a imitar.","B":"Não se trata apenas de uma mudança neutra do significado de alegria.","C":"Mesmo estilos de vida acessíveis podem ser editados; inacessibilidade econômica não define o fenômeno.","D":"Não é necessário comprovar incoerência pessoal dos influenciadores para existir essa pressão.","E":"O corpo é um exemplo, mas a idealização inclui casas, viagens, consumo e emoções."},"takeaway":"Uma alternativa pode citar um exemplo verdadeiro e ainda ser estreita demais para a definição do fenômeno.","key":"linguagens:L733","area":"linguagens","year":2022,"number":37,"answer":"A","subject":"Tecnologias da Informação e Comunicação","topic":"Cultura digital, redes e gêneros digitais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A figura alongada distingue a solução maneirista","steps":["A cena recupera Laocoonte, tema da Antiguidade.","Os corpos alongados, torsos contorcidos e proporções expressivamente alteradas chamam atenção na pintura.","B reconhece a distorção da figura humana como traço distintivo, não a simples presença de um tema clássico."],"alternatives":{"A":"O nu masculino aparece em diferentes épocas e não distingue o Maneirismo.","B":"Proporções alongadas e torções artificiosas afastam as figuras de um naturalismo equilibrado.","C":"Temas gregos também estão presentes em outras tradições artísticas.","D":"A narrativa da morte explica o assunto, mas não o tratamento formal maneirista.","E":"Perspectiva e planos não constituem, aqui, a particularidade mais marcante solicitada."},"takeaway":"Em história da arte, diferencie iconografia, o tema representado, de tratamento formal, como ele é construído.","key":"linguagens:L623","area":"linguagens","year":2022,"number":38,"answer":"B","subject":"Artes","topic":"História da arte e outras manifestações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Unidades simples se combinam com o espaço da instalação","steps":["A fotografia mostra módulos geométricos semelhantes, dispostos verticalmente com intervalos.","O texto aproxima essas estruturas de materiais industriais e formas aparentemente simples.","E identifica a articulação de formas sintéticas no espaço, não a representação de um objeto cotidiano reconhecível."],"alternatives":{"A":"Simplicidade é característica, mas a obra não se reduz a representar uma ideia abstrata de ser simples.","B":"Não se trata de decompor e remontar um objeto segundo o repertório cubista.","C":"A forma geométrica não basta para afirmar que a finalidade seja valorizar o cotidiano.","D":"O texto destaca redução e clareza das formas, não complexidade ornamental.","E":"Módulos e vazios se organizam espacialmente e participam da experiência da obra."},"takeaway":"No Minimalismo, forma, material, repetição e relação com o espaço podem importar mais que representar algo externo.","key":"linguagens:L624","area":"linguagens","year":2022,"number":39,"answer":"E","subject":"Artes","topic":"História da arte e outras manifestações","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[17],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A notícia da morte revela afeto contido","steps":["O personagem reconhece a ausência de resposta a um verso como sinal de que algo ocorreu.","Ao relatar a morte, fica comovido e se afasta para esconder as lágrimas.","D identifica o vínculo afetivo que intensifica a expressividade lírica da cena."],"alternatives":{"A":"A imagem do gado situa a cena, mas não é a fonte central de emoção.","B":"Preparar a montaria é uma ação circunstancial, não o núcleo lírico.","C":"Não há desenvolvimento da pobreza como motivo principal do trecho.","D":"A lembrança do cantador, a comoção e as lágrimas tornam sensível a perda.","E":"Ocultar as lágrimas pode envolver normas de masculinidade, mas a cena enfatiza o afeto, não a exibição de virilidade."},"takeaway":"Um gesto de contenção pode revelar uma emoção justamente por tentar escondê-la.","key":"linguagens:L448","area":"linguagens","year":2022,"number":40,"answer":"D","subject":"Literatura","topic":"Pré-Modernismo","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"Desejo e repulsa convivem no olhar do personagem","steps":["O narrador se deixa atrair pela liberdade anônima do carnaval.","Ao mesmo tempo, chama o próprio impulso de mórbido e ignóbil.","B reconhece atração e asco diante das atitudes libertinas, sem confundir voz da personagem com julgamento do autor."],"alternatives":{"A":"O tom não é de celebração coletiva sem tensão ou ambivalência.","B":"O impulso desejado é acompanhado por qualificações depreciativas e repulsa.","C":"O foco não é a surpresa diante de uma multidão numerosa.","D":"O contato anônimo é desejado, mas a alternativa não contempla o julgamento negativo simultâneo.","E":"Reconhecer a festa culturalmente não explica a contradição afetiva expressa."},"takeaway":"Palavras de avaliação podem contrariar o impulso narrado: procure sinais de ambivalência, não só de desejo.","key":"linguagens:L449","area":"linguagens","year":2022,"number":41,"answer":"B","subject":"Literatura","topic":"Pré-Modernismo","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A ironia expõe os limites do conselho da autoridade","steps":["O tenente apresenta à mãe uma generalização sobre os riscos da favela.","A autora pergunta por que ele não dirige esse diagnóstico aos políticos capazes de agir.","D identifica a resposta irônica que devolve a responsabilidade ao poder público, sem endossar o estigma contra moradores."],"alternatives":{"A":"A reflexão questiona a utilidade do discurso do tenente; não o aceita como uma lição suficiente.","B":"O eixo é uma crítica social argumentada, não uma disposição emotiva materna.","C":"O trecho não descreve uma organização política ativa da comunidade.","D":"Perguntar por que se fala à lixeira e não aos governantes expõe a inadequação da cobrança.","E":"A escrita íntima do diário existe, mas a reflexão alcança fome e responsabilidade política."},"takeaway":"Em Carolina Maria de Jesus, experiência pessoal e crítica às estruturas sociais se articulam sem reduzir a autora a seu sofrimento.","key":"linguagens:L372","area":"linguagens","year":2022,"number":42,"answer":"D","subject":"Literatura","topic":"Literatura contemporânea (pós-1960)","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[18],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A anedota doméstica deixa aparecer uma história de violência","steps":["O relato combina referências de folhetim a lembranças contadas por Vanda.","A narradora recorda agressões graves em cenas breves do cotidiano da cozinha.","E identifica a forma anedótica de apresentar esses atos, sem que isso os torne leves, aceitáveis ou inventados."],"alternatives":{"A":"As referências literárias ajudam a caracterizar a trajetória, mas não bastam para explicar o efeito do relato.","B":"As crianças são chamadas de mimadas, não elevadas a símbolo de inocência.","C":"Não se formula uma tese geral sobre a bondade humana.","D":"A origem mineira não resulta em uma descrição detalhada dos habitantes do interior.","E":"As memórias dolorosas surgem como casos contados na convivência doméstica, com contraste de tom."},"takeaway":"Representar violência em registro anedótico é um procedimento narrativo; reconhecê-lo não significa naturalizar a violência.","key":"linguagens:L373","area":"linguagens","year":2022,"number":43,"answer":"E","subject":"Literatura","topic":"Literatura contemporânea (pós-1960)","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"A ausência do objeto questiona a expectativa do que seja arte","steps":["Duchamp desloca objetos comuns para o espaço de exposição.","Regina Silveira apresenta sombras projetadas sem a presença correspondente da roda e do banco.","C aproxima as obras pela contestação de valores estéticos estabelecidos e das expectativas sobre objeto e representação."],"alternatives":{"A":"A obra posterior dialoga com Duchamp, mas não simplesmente repete uma forma de criticar o passado.","B":"A mera recorrência de tema não explica a operação crítica compartilhada.","C":"Objeto comum e sombra sem objeto desestabilizam noções convencionais de obra e valor artístico.","D":"A passagem do tempo não é, por si, a razão dessa transformação de referência.","E":"Ausência não significa desgaste ou degradação material da forma representada."},"takeaway":"Intertextualidade artística pode atualizar uma pergunta sobre arte, em vez de copiar a aparência de uma obra anterior.","key":"linguagens:L568","area":"linguagens","year":2022,"number":44,"answer":"C","subject":"Artes","topic":"Arte contemporânea e linguagens visuais","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}},{"title":"O manguebeat renova pela mistura, não pela substituição","steps":["O texto reúne maracatu e alfaias com hip-hop, rock e eletrônica.","As referências locais permanecem ativas, inclusive no sotaque e no imaginário do mangue.","E identifica integração de origens diferentes em uma nova combinação estética."],"alternatives":{"A":"Instrumentos e referências tradicionais se combinam aos eletrônicos, sem serem eliminados.","B":"Mangue é referência simbólica e cultural, não uma exigência de tocar dentro de um manguezal.","C":"A inovação não depende de substituir ou extinguir o frevo e práticas anteriores.","D":"O movimento não se resume a reapresentar composições folclóricas em festivais.","E":"A interação entre repertórios locais e circuitos musicais diversos cria a renovação descrita."},"takeaway":"Hibridização cultural pode valorizar referências locais ao mesmo tempo que as transforma pelo contato com outras linguagens.","key":"linguagens:L598","area":"linguagens","year":2022,"number":45,"answer":"E","subject":"Artes","topic":"Música e patrimônio cultural","status":"verified","annulled":false,"provenance":{"officialKeyURL":"https://download.inep.gov.br/enem/provas_e_gabaritos/2022_GB_impresso_D1_CD1.pdf","officialDocumentMirror":false,"officialKeyPDF":"/workspace/apostila-enem/linguagens/gab_2022.pdf","sha256":"023dda43b3b4e7b275d7155d9d856451dc14d607f891601c65f9a0fcc3c8ed7e","verified":true,"originalDefault":false,"sourceExamPDF":"/workspace/apostila-enem/linguagens/prova_2022.pdf","sourceExamPages":[19],"reviewMethod":"Leitura integral do texto e alternativas; figuras conferidas quando necessárias; comparação independente com gabarito oficial."}}];
